package io.knowledgebrain.collaboration;
import io.knowledgebrain.contracts.collaboration.rubricassessment.v1.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_GROUP_KAFKA_BOOTSTRAP",matches=".+")
class RubricAssessmentKafkaIntegrationTest {
 @Test void fullImmutableGradeBasisMatchesCdcBytesAndUnacknowledgedReplay()throws Exception{
  var test=new RubricGradingStoreIntegrationTest();test.setup();var first=test.change(0,test.input(45,30,"Same total"));test.change(1,test.input(50,25,"Same total"));test.change(2,test.direct(75,"Same total",1,2));test.change(3,test.input(45,30,"Same total"));var f=test.f.f;var expected=new HashMap<String,byte[]>();for(var bytes:f.f.jdbc.queryForList("SELECT o.payload FROM outbox_event o JOIN submission_rubric_assessment a ON o.aggregateid=a.assessment_id WHERE a.submission_id=?",byte[].class,test.answer.submissionId())){var e=RubricAssessmentEnvelopeV1.parseFrom(bytes);expected.put(e.getEventId(),bytes);}assertEquals(3,expected.size());
  var options=new Properties();options.put("bootstrap.servers",System.getenv("BRAIN_TEST_GROUP_KAFKA_BOOTSTRAP"));options.put("group.id","group-validation-"+UUID.randomUUID());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",StringDeserializer.class.getName());options.put("value.deserializer",ByteArrayDeserializer.class.getName());options.put("security.protocol","SSL");options.put("ssl.endpoint.identification.algorithm","HTTPS");options.put("ssl.truststore.type","PEM");options.put("ssl.keystore.type","PEM");options.put("ssl.truststore.certificates",Files.readString(Path.of("/group-kafka-test/ca.crt")));options.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/group-kafka-test/user.crt")));options.put("ssl.keystore.key",Files.readString(Path.of("/group-kafka-test/user.key")));
  for(int replay=0;replay<2;replay++){var seen=new HashSet<String>();var versions=new HashSet<Long>();try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(List.of("collaboration.rubric-assessment.v1"));long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(seen.size()<3&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofMillis(300))){var e=RubricAssessmentEnvelopeV1.parseFrom(record.value());if(!expected.containsKey(e.getEventId()))continue;assertArrayEquals(expected.get(e.getEventId()),record.value());var p=RubricAssessmentSnapshotV1.parseFrom(e.getPayload());assertEquals(p.getAssessmentId(),record.key());assertEquals(first.grade().gradeId().toString(),p.getGradeId());assertEquals(75,p.getScore());assertEquals(1,p.getVersion());assertEquals(1,p.getRubric().getAssignmentVersion());assertEquals(2,p.getAssignmentVersion());assertEquals("AUTHOR_AND_OWNER",p.getAudience());assertEquals(100,p.getRubric().getCriteriaList().stream().mapToInt(n->n.getMaxPoints()).sum());assertEquals(p.getScore(),p.getCriteriaList().stream().mapToInt(n->n.getScore()).sum());for(var entry:Map.of("trace_id",f.f.trace,"schema_group","collaboration","schema_artifact","rubric-assessment-events","schema_version","1").entrySet())assertEquals(entry.getValue(),new String(record.headers().lastHeader(entry.getKey()).value(),StandardCharsets.UTF_8));assertEquals(f.f.trace,e.getTraceId());assertEquals(f.space.toString(),e.getSpaceId());seen.add(e.getEventId());versions.add(p.getGradeVersion());}}assertEquals(expected.keySet(),seen);assertEquals(Set.of(1L,2L,4L),versions);}
  System.out.println("PASS immutable rubric assessment3 exact CDC snapshots/replay, same total different basis, manual gap, source and trace/schema");
 }
}
